def batch_search_parallel(queries, index, top_k=10, num_workers=None, documents=None):
    start_time = time.perf_counter()
    if num_workers is None:
        num_workers = mp.cpu_count()
    doc_titles = {d.doc_id: d.title for d in documents} if documents else None
    def search_one(q):
        return _search_query(q, index, top_k, doc_titles)
    with ThreadPoolExecutor(max_workers=num_workers) as executor:
        results = list(executor.map(search_one, queries))
    elapsed = time.perf_counter() - start_time
    return results, elapsed
